(function(E){ const x = E["hr-m8"] = E["hr-m8"] || {units:{}}; x.units["hr-cp-8"] = {"writing":{"id":"c-hr-cp-8-w","course":"hr","unit":"hr-cp-8","title":{"en":"Yusuf’s outcome letter","tr":"Yusuf’un sonuç mektubu","fa":"نامه‌ی نتیجه‌ی یوسف"},"type":"writing","difficulty":"hard","portfolio":null,"prompt":{"en":"Write the outcome letter to Yusuf (80-110 words): the meeting, what the records show, the decision (a first written warning) and how long it stays on file, what must change, what happens if it happens again, and how to appeal.","tr":"Yusuf’a sonuç mektubunu yaz (80-110 kelime): görüşme, kayıtların gösterdiği, karar (ilk yazılı uyarı) ve dosyada ne kadar kalacağı, neyin değişmesi gerektiği, tekrar olursa ne olacağı ve nasıl itiraz edileceği.","fa":"نامه‌ی نتیجه را برای یوسف بنویس (۸۰ تا ۱۱۰ کلمه): جلسه، چیزی که سوابق نشان می‌دهند، تصمیم (اولین اخطار کتبی) و اینکه چقدر در پرونده می‌ماند، چیزی که باید تغییر کند، اینکه اگر تکرار شود چه می‌شود و راه اعتراض."},"model":"Dear Yusuf, following our meeting on 8 May, I have considered your explanation and the records. The records show that the safety checks on 4 and 6 May were not completed, although the paper log was signed. As a result, you are receiving a first written warning, which will stay on file for six months. From now on, every check must be done before a van leaves, on paper if the tablet fails. A similar problem may lead to a final written warning. If you disagree with this decision, you can appeal in writing to Ms Clarke within five working days. Yours sincerely, Leyla Karimi","frame":"Dear ___, following our meeting on ___, I have considered ___. The records show that ___. As a result, you are receiving ___, which will stay on file for ___. From now on, ___. A similar problem may lead to ___. If you disagree with this decision, you can appeal ___ within ___. Yours sincerely, ___","words":[{"word":"following"},{"word":"the records show"},{"word":"appeal"}],"minWords":80,"minSentences":6,"rubric":["Task done: meeting, facts, decision and time on file, change needed, next step if repeated, appeal","Organised: event, facts, decision, change, appeal","Language: neutral facts and formal linking (the records show, as a result)","Tone: formal, fair and firm"],"rubricI18n":{"tr":["Görev: görüşme, olgular, karar ve dosyada kalma süresi, gereken değişiklik, tekrarında olacaklar, itiraz","Düzen: olay, olgular, karar, değişiklik, itiraz","Dil: tarafsız olgular ve resmî bağlaçlar (the records show, as a result)","Üslup: resmî, adil ve kararlı"],"fa":["کامل بودن کار: جلسه، واقعیت‌ها، تصمیم و مدت ماندن در پرونده، تغییر لازم، قدم بعدی در صورت تکرار، اعتراض","نظم: اتفاق، واقعیت‌ها، تصمیم، تغییر، اعتراض","زبان: واقعیت‌های بی‌طرف و ربط‌دهنده‌های رسمی (the records show، as a result)","لحن: رسمی، منصفانه و قاطع"]},"parts":[{"t":{"en":"The meeting","tr":"Toplantı","fa":"جلسه"},"find":["following our meeting","following"],"sample":"the meeting on 8 May"},{"t":{"en":"What the records show","tr":"Kayıtların gösterdiği","fa":"چیزی که سوابق نشان می‌دهند"},"find":["the records show"],"sample":"checks on 4 and 6 May not done; the log was signed"},{"t":{"en":"The decision, and how long it stays on file","tr":"Karar ve dosyada ne kadar kalacağı","fa":"تصمیم و اینکه چقدر در پرونده می‌ماند"},"find":["written warning","on file"],"sample":"a first written warning, six months on file"},{"t":{"en":"What must change","tr":"Neyin değişmesi gerektiği","fa":"چیزی که باید عوض شود"},"find":["from now on","must"],"sample":"every check before a van leaves"},{"t":{"en":"What happens next time, and how to appeal","tr":"Bir dahaki sefere ne olacağı ve nasıl itiraz edileceği","fa":"دفعه‌ی بعد چه می‌شود و چطور اعتراض کند"},"find":["may lead to","appeal"],"sample":"a final written warning; appeal to Ms Clarke within five days"}]},"speaking":{"id":"hr-cp-8-sp","course":"hr","unit":"hr-cp-8","rounds":[180,120],"topic":{"en":"A Change After Leave (recorded)","tr":"İzin Sonrası Bir Değişiklik (kayıtlı)","fa":"یک تغییر بعد از مرخصی (ضبط‌شده)"},"warmup":{"en":"Deniz is back from parental leave. The baby does not sleep, and he asks to move from night shifts to day shifts for three months.","tr":"Deniz ebeveyn izninden döndü. Bebek uyumuyor ve üç ay boyunca gece vardiyasından gündüz vardiyasına geçmek istiyor.","fa":"دنیز از مرخصی والدین برگشته. بچه نمی‌خوابد و او می‌خواهد سه ماه از شیفت شب به شیفت روز برود."},"questions":[{"en":"Congratulate Deniz and ask what would help most.","tr":"Deniz’i tebrik et ve en çok neyin yardımcı olacağını sor.","fa":"به دنیز تبریک بگو و بپرس چه چیزی بیشتر کمکش می‌کند."},{"en":"Present a possible change as a proposal, with exact dates (from... to).","tr":"Olası bir değişikliği kesin tarihlerle (from... to) bir öneri olarak sun.","fa":"یک تغییر ممکن را به‌صورت پیشنهاد و با تاریخ دقیق (from... to) مطرح کن."},{"en":"Say why it helps, and agree a review date.","tr":"Neden yardımcı olacağını söyle ve bir gözden geçirme tarihinde anlaş.","fa":"بگو چرا کمک می‌کند و روی یک تاریخ بازبینی توافق کن."}],"followups":[{"en":"Say it out loud in 3 minutes, then in 2.","tr":"Yüksek sesle önce 3, sonra 2 dakikada söyle.","fa":"آن را با صدای بلند یک بار در سه دقیقه و بعد در دو دقیقه بگو."}],"expressions":[{"phrase":"What would help you most?","meaning":{"en":"Lets the person suggest the change.","tr":"Değişikliği kişinin önermesine fırsat verir.","fa":"به فرد فرصت می‌دهد خودش تغییر را پیشنهاد بدهد."}},{"phrase":"We are proposing to move you to days from 1 June to 31 August.","meaning":{"en":"A proposal with exact dates.","tr":"Kesin tarihli bir öneri.","fa":"پیشنهادی با تاریخ‌های دقیق."}},{"phrase":"Let’s review it at the end of July.","meaning":{"en":"Agrees a review.","tr":"Bir gözden geçirmede anlaşır.","fa":"روی بازبینی توافق می‌کند."}}]},"perspective":{"id":"c-hr-cp-8-p","course":"hr","unit":"hr-cp-8","type":"perspective","title":{"en":"Leyla, looking back","tr":"Geriye bakan Leyla","fa":"لیلا، با نگاهی به گذشته"},"minSentences":3,"prompt":{"en":"You are Leyla. Write 3 sentences in first person: which of the four cases in this chapter (Yusuf, the summer shift, Ece and Deniz, Rania) was the hardest to keep fair, and why?","tr":"Sen Leyla’sın. Birinci tekil şahısla 3 cümle yaz: bu bölümdeki dört dosyadan (Yusuf, yaz vardiyası, Ece ve Deniz, Rania) hangisinde adil kalmak en zordu ve neden?","fa":"تو لیلا هستی. از زبان خودت سه جمله بنویس: از چهار پرونده‌ی این فصل (یوسف، شیفت تابستان، اِجه و دنیز، رانیا) منصفانه ماندن در کدام سخت‌تر بود و چرا؟"}},"exit":{"id":"c-hr-cp-8-x","course":"hr","unit":"hr-cp-8","type":"exit","note":"8 spaced items: all four Chapter 8 lessons plus four earlier chapters.","items":[{"from":"hr-8-1","kind":"blank","prompt":"The records ___ that two checks were missed.","options":["show","shows to","showing"],"correct":0,"point":2,"why":{"en":"show: 'the records' is plural, so the present simple without -s. 'Shows to' adds -s and a wrong 'to', and 'showing' is not a full verb.","tr":"show: 'the records' çoğuldur, bu yüzden -s'siz geniş zaman. 'Shows to' -s ve yanlış bir 'to' ekler; 'showing' tam fiil değildir.","fa":"⁨show⁩ درست است، چون ⁨the records⁩ جمع است و حال ساده بدون ⁨-s⁩ می‌آید. ⁨shows to⁩ ⁨-s⁩ و یک ⁨to⁩ غلط دارد و ⁨showing⁩ فعل کامل نیست."}},{"from":"hr-8-2","kind":"blank","prompt":"We are considering ___ a company bus.","options":["adding","to add","add"],"correct":0,"point":2,"why":{"en":"adding: 'consider' takes -ing. 'To add' and 'add' don't follow considering.","tr":"adding: 'consider' -ing alır. 'To add' ve 'add' considering'den sonra gelmez.","fa":"adding درست است، چون بعد از consider فعل ing‌دار می‌آید. to add و add بعد از considering نمی‌آیند."}},{"from":"hr-8-3","kind":"blank","prompt":"Her leave runs ___ 1 March to 29 April.","options":["from","for","within"],"correct":0,"point":2,"why":{"en":"from: 'from 1 March to 29 April' gives the start and the end. 'For' gives a length, and 'within' is 'before the end of'.","tr":"from: 'from 1 March to 29 April' başlangıcı ve bitişi verir. 'For' bir süre verir; 'within' 'bitmeden önce' demektir.","fa":"from درست است، چون from 1 March to 29 April شروع و پایان را می‌گوید. for طول مدت را می‌گوید و within یعنی قبل از پایان."}},{"from":"hr-8-4","kind":"blank","prompt":"We moved her desk ___ the light was softer.","options":["so that","to","for"],"correct":0,"point":2,"why":{"en":"so that: a full clause follows (the light was softer). 'To' needs a verb, and 'for' doesn't give a purpose with a clause.","tr":"so that: ardından tam bir yan cümle gelir (the light was softer). 'To' bir fiil ister; 'for' bir yan cümleyle amaç bildirmez.","fa":"so that درست است، چون بعدش جمله‌ی کامل می‌آید. to فعل می‌خواهد و for با جمله هدف را نشان نمی‌دهد."}},{"from":"hr-7-4","kind":"blank","prompt":"___ our meeting on 3 June, we reviewed the records.","options":["Following","Following to","After of"],"correct":0,"point":2,"why":{"en":"Following: 'Following our meeting' means after it, in formal letters. 'Following to' and 'After of' add a wrong preposition.","tr":"Following: resmî yazılarda 'Following our meeting' toplantımızdan sonra demektir. 'Following to' ve 'After of' yanlış bir edat ekler.","fa":"Following درست است، چون در نامه‌ی رسمی Following our meeting یعنی بعد از جلسه‌مان. following to و after of حرف اضافه‌ی غلط دارند."}},{"from":"hr-5-2","kind":"mcq","prompt":"Which feedback has a situation, a behaviour and an impact?","options":["You are careless.","Great job last week!","On Tuesday you sent the report late, so the client meeting was moved."],"correct":2,"point":1,"why":{"en":"It names the situation (Tuesday), the behaviour (sent late) and the impact (meeting moved). 'You are careless' judges the person, and 'Great job!' gives no detail.","tr":"Durumu (salı), davranışı (geç gönderildi) ve etkiyi (toplantı ertelendi) söyler. 'You are careless' kişiyi yargılar; 'Great job!' ayrıntı vermez.","fa":"موقعیت (سه‌شنبه)، رفتار (دیر فرستادن) و اثر (عقب افتادن جلسه) را می‌گوید. You are careless آدم را قضاوت می‌کند و Great job! جزئیاتی ندارد."}},{"from":"hr-4-1","kind":"blank","prompt":"Part-time staff are ___ to sick pay.","options":["entitled","allowed","given"],"correct":0,"point":2,"why":{"en":"entitled: 'entitled to' means it is their right. 'Allowed' is permission, and 'given to' doesn't make this meaning.","tr":"entitled: 'entitled to' bunun onların hakkı olduğu demektir. 'Allowed' izindir; 'given to' bu anlamı vermez.","fa":"entitled درست است، چون entitled to یعنی حق آن‌هاست. allowed یعنی اجازه و given to این معنی را نمی‌دهد."}},{"from":"hr-2-2","kind":"mcq","prompt":"Which wording is free of bias?","options":["Fluent English (spoken and written)","Young, native English speaker","Strong man wanted"],"correct":0,"point":1,"why":{"en":"'Fluent English (spoken and written)' describes the job's need. 'Young, native speaker' and 'strong man' exclude people by age, origin or sex.","tr":"'Fluent English (spoken and written)' işin ihtiyacını anlatır. 'Young, native speaker' ve 'strong man' insanları yaş, köken ya da cinsiyete göre dışlar.","fa":"«Fluent English (spoken and written)» نیاز خود کار را می‌گوید. «Young, native speaker» و «Strong man» آدم‌ها را بر اساس سن، ملیت یا جنسیت کنار می‌گذارند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
